  Object.assign(q[0], {title:"¿Cuál es el origen de Suecia?",reaction:"Ya sabemos que Suecia fue un país que tardó siglos en formarse."});
  Object.assign(q[1], {title:"El verdadero casco vikingo",reaction:"Hemos quitado el disfraz del vikingo con cuernos. Ahora ya sabemos cómo eran los vikingos de verdad."});
